import { serializeTask } from "../store.js";

function listPage(tasks, query) {
	const fail = (code, message) => ({ status: 400, body: { error: { code, message } } });
	const raw = query.get("limit");
	const limit = raw === null ? 25 : Number(raw);
	if ((raw !== null && !/^\d+$/.test(raw)) || !Number.isInteger(limit) || limit < 1 || limit > 50) {
		return fail("invalid_limit", "limit must be an integer between 1 and 50");
	}
	const status = query.get("status");
	if (status !== null && status !== "open" && status !== "done") {
		return fail("invalid_status", "status must be open or done");
	}
	const visible = [...tasks].filter((task) => !task.deleted_at && (status === null || task.status === status));
	visible.sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
	let after = null;
	if (query.has("cursor")) {
		try {
			const cursor = query.get("cursor");
			if (!cursor || !/^[A-Za-z0-9_-]+$/.test(cursor)) throw new Error();
			const bytes = Buffer.from(cursor, "base64url");
			if (bytes.toString("base64url") !== cursor) throw new Error();
			const decoded = JSON.parse(bytes.toString("utf8"));
			if (!Array.isArray(decoded) || decoded.length !== 3 || decoded[0] !== 1 ||
				typeof decoded[1] !== "string" || !/^[0-7][0-9A-HJKMNP-TV-Z]{25}$/.test(decoded[1]) ||
				decoded[2] !== status) throw new Error();
			after = decoded[1];
		} catch {
			return fail("invalid_cursor", "cursor is invalid for this query");
		}
	}
	const remaining = visible.filter((task) => after === null || task.id > after);
	const page = remaining.slice(0, limit);
	const next_cursor = remaining.length > limit
		? Buffer.from(JSON.stringify([1, page[page.length - 1].id, status])).toString("base64url")
		: null;
	return { status: 200, body: { items: page.map(serializeTask), next_cursor } };
}
